const unit=()=>{let u=state.units.find(x=>x.id===state.unit),h=u.hours?.[new Date(TODAY+'T12:00:00').getDay()];return h?{...u,open:h.open,close:h.close}:u},dogBy=id=>state.dogs.find(x=>x.id===id),tutorBy=id=>state.tutors.find(x=>x.id===id),planBy=id=>state.plans.find(x=>x.id===id),dogs=()=>state.dogs.filter(x=>x.unit===state.unit),present=()=>state.visits.filter(v=>!v.out&&dogBy(v.dog)?.unit===state.unit),contract=id=>state.contracts.find(x=>x.dog===id&&x.status==='Ativo'&&x.start<=TODAY&&x.end>=TODAY),balance=c=>(c?.credits||0)+state.movements.filter(x=>x.contract===c?.id).reduce((a,b)=>a+b.delta,0),total=f=>f.items.reduce((a,x)=>a+x.qty*x.price,0)-f.discount,invoiceStatus=f=>f.paid>=total(f)?'Pago':f.due<TODAY?'Vencido':'Em aberto';
