function paginate(items,renderItem){let n=Math.max(1,Math.ceil(items.length/8));listPage=Math.min(listPage,n);return renderItem(items.slice((listPage-1)*8,listPage*8))+`<div class="page-count">${items.length} registros ${btn('Anterior','prev','small')} ${listPage} / ${n} ${btn('Próxima','next','small')}</div>`}
function dogMatch(d){return `${d.name} ${d.breed} ${d.tutors.map(t=>tutorBy(t)?.name).join(' ')}`.toLowerCase().includes(search.toLowerCase())}
