function render(){if(!state.session){login();return}if(!canView(page))page='dashboard';document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">m</span>matilha<em>os</em></div><div class="navlabel">Sua operação</div><nav class="nav" aria-label="Menu principal">${navItems.filter(([id])=>canView(id)).map(([id,i,t],n)=>`${id==='caes'?'<div class="navlabel">Gestão da creche</div>':''}${btn(t,`nav:${id}`,id===page?'active':'',i)}`).join('')}</nav><div class="side-bottom"><span class="prototype">Protótipo interativo</span><p>Dados fictícios. Alterações salvas apenas neste navegador.</p>${btn('Sobre o protótipo','about','textlink')}</div></aside><main class="main"><header class="topbar"><div class="unit">${btn('','menu','ghost mobile-menu','menu')}${icon('building')}<div><small>Unidade ativa</small>${select('unit',state.units.map(u=>[u.id,u.name]),state.unit,'aria-label="Unidade ativa" data-unit')}</div></div><div class="top-actions">${btn('','nav:alertas','ghost','bell')}<button class="user ghost" data-action="profile" aria-label="Perfil e sessão"><span class="avatar">LM</span><div>Laura Martins<small>${state.role}</small></div></button></div></header><div class="content" id="maincontent">${view()}<div class="footer-note">MatilhaOS · Operação Serena · Demonstração de 17/09/2026</div></div></main></div>`;document.querySelectorAll('button[data-action="nav:alertas"]').forEach(b=>{if(!b.textContent.trim())b.setAttribute('aria-label','Notificações')});document.querySelectorAll('button[data-action="menu"]').forEach(b=>b.setAttribute('aria-label','Abrir menu'));}
